import json
import unittest
from pathlib import Path

from inventory import Client, collect


class InventoryTest(unittest.TestCase):
    def test_enabled_jobs(self):
        client = Client(
            {
                "/jobs?limit=2": {
                    "items": [
                        {"name": "build", "enabled": True},
                        {"name": "nightly", "enabled": False},
                    ],
                    "next": None,
                }
            }
        )
        self.assertEqual(collect(client), ["build"])

    def test_empty(self):
        client = Client({"/jobs?limit=2": {"items": [], "next": None}})
        self.assertEqual(collect(client), [])

    def test_saved_responses_include_every_enabled_job(self):
        responses = json.loads(
            (Path(__file__).resolve().parents[1] / "api.json").read_text(
                encoding="utf-8"
            )
        )
        client = Client(responses)
        self.assertEqual(collect(client), ["build", "deploy"])
        self.assertEqual(client.calls, ["/jobs?limit=2", "/jobs?cursor=2"])

    def test_filters_and_sorts_across_pages_including_an_empty_page(self):
        client = Client(
            {
                "/jobs?limit=2": {
                    "items": [{"name": "zeta", "enabled": True}],
                    "next": "/jobs?cursor=empty",
                },
                "/jobs?cursor=empty": {
                    "items": [],
                    "next": "/jobs?cursor=last",
                },
                "/jobs?cursor=last": {
                    "items": [
                        {"name": "alpha", "enabled": True},
                        {"name": "disabled", "enabled": False},
                    ],
                    "next": None,
                },
            }
        )
        self.assertEqual(collect(client), ["alpha", "zeta"])
        self.assertEqual(
            client.calls,
            ["/jobs?limit=2", "/jobs?cursor=empty", "/jobs?cursor=last"],
        )


if __name__ == "__main__":
    unittest.main()

